parameters.jsCode:
const m2Input = $('Validate M2 Input').item.json.m2_input || $('Execute Workflow Trigger').item.json;
const llmRaw = $json;

function safeParse(value) {
 if (typeof value === 'object' && value !== null) return value;

 if (typeof value === 'string') {
   try {
     return JSON.parse(value);
   } catch (e) {
     const match = value.match(/\{[\s\S]*\}/);
     if (match) {
       try {
         return JSON.parse(match[0]);
       } catch (_) {}
     }
   }
 }

 return {};
}

const parsed = safeParse(
 llmRaw.output ||
 llmRaw.text ||
 llmRaw.response ||
 llmRaw.message ||
 llmRaw
);

const allowedResponseTypes = [
 'discovery',
 'recommendation',
 'product_detail',
 'clarification',
 'out_of_scope'
];

const allowedNextSteps = [
 'ask_clarification',
 'show_options',
 'show_product',
 'invite_purchase',
 'handoff_suggested',
 'none'
];

const response = parsed.response || {};
const catalog = parsed.catalog || {};
const presentation = parsed.presentation || {};
const memoryUpdate = parsed.memory_update || {};
const control = parsed.control || {};

const responseType = allowedResponseTypes.includes(response.response_type)
 ? response.response_type
 : 'clarification';

const nextStep = allowedNextSteps.includes(response.next_step)
 ? response.next_step
 : 'ask_clarification';

const replyText = String(response.replyText || '').trim() ||
 'Para orientarte mejor, ¿me cuentas qué tipo de producto estás buscando?';

return [
 {
   json: {
     schema_version: 'dalia.m3.advisor_response.v1',
     trace: {
       event_id: m2Input.trace?.event_id || null,
       conversation_id: m2Input.trace?.conversation_id || null,
       session_id: m2Input.trace?.session_id || null
     },
     context: {
       environment: m2Input.context?.environment || null,
       business_id: m2Input.context?.business_id || null,
       channel: m2Input.context?.channel || null,
       user_id: m2Input.context?.user_id || null,
       display_name: m2Input.context?.display_name || null
     },
     response: {
       replyText,
       response_type: responseType,
       next_step: nextStep
     },
     catalog: {
       used_catalog: catalog.used_catalog !== false,
       matched: Boolean(catalog.matched),
       match_type: catalog.match_type || 'none',
       items: Array.isArray(catalog.items) ? catalog.items : []
     },
     presentation: {
       sendImage: Boolean(presentation.sendImage),
       image_mode: presentation.image_mode || 'none',
       image_candidates: Array.isArray(presentation.image_candidates)
         ? presentation.image_candidates
         : []
     },
     memory_update: {
       product_consulted: memoryUpdate.product_consulted || null,
       preference_detected: memoryUpdate.preference_detected || null,
       city_detected: memoryUpdate.city_detected || null
     },
     control: {
       can_continue: control.can_continue !== false,
       handoff_suggested: Boolean(control.handoff_suggested),
       purchase_signal_detected: Boolean(control.purchase_signal_detected),
       fallback_reason: control.fallback_reason || null
     }
   }
 }
];

const output = $json;

const replyText = String(output.response?.replyText || '');
const lower = replyText.toLowerCase();

const forbiddenTerms = [
 'sku',
 'qdrant',
 'rag',
 'n8n',
 'workflow',
 'módulo',
 'modulo',
 'herramienta interna',
 'base vectorial',
 'embedding'
];

const violations = [];

if (!replyText.trim()) {
 violations.push('empty_reply');
}

for (const term of forbiddenTerms) {
 if (lower.includes(term)) {
   violations.push(`forbidden_term_${term}`);
 }
}

const mentionsPrice =
 /\$\s?\d+|\bprecio\b|\bvale\b|\bcop\b|\bpesos\b/i.test(replyText);

if (mentionsPrice && !output.catalog?.items?.some(item => item.price)) {
 violations.push('possible_price_invention');
}

const mentionsStock =
 /\bstock\b|\bdisponible\b|\binventario\b|\bhay unidades\b/i.test(replyText);

if (mentionsStock && !output.catalog?.items?.some(item => item.stock_status)) {
 violations.push('possible_stock_invention');
}

if (output.presentation?.sendImage === true) {
 const candidates = output.presentation?.image_candidates || [];
 if (!Array.isArray(candidates) || candidates.length === 0) {
   violations.push('send_image_without_candidate');
 }
}

if (
 output.response?.response_type === 'product_detail' &&
 (!output.catalog?.items || output.catalog.items.length === 0)
) {
 violations.push('product_detail_without_catalog_item');
}

if (violations.length > 0) {
 return [
   {
     json: {
       ...output,
       response: {
         replyText: 'No tengo suficiente información confiable sobre ese producto dentro del catálogo demo. Puedo ayudarte a revisar las opciones disponibles.',
         response_type: 'out_of_scope',
         next_step: 'ask_clarification'
       },
       catalog: {
         used_catalog: true,
         matched: false,
         match_type: 'none',
         items: []
       },
       presentation: {
         sendImage: false,
         image_mode: 'none',
         image_candidates: []
       },
       control: {
         can_continue: true,
         handoff_suggested: false,
         purchase_signal_detected: false,
         fallback_reason: 'guardrail_validation_failed'
       },
       guardrail: {
         passed: false,
         violations
       }
     }
   }
 ];
}

return [
 {
   json: {
     ...output,
     guardrail: {
       passed: true,
       violations: []
     }
   }
 }
];
